import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`cookbook-creator`,heroTitle:`Turn your recipes into a cookbook business`,heroSubtitle:`Perplexity Computer organizes your recipes, builds meal plans and grocery lists, and creates your sales page and launch sequence — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Organizing your recipes into themed cookbook sections`,`Building meal plans, grocery lists, and a paid download package`,`Writing sales page copy, email sequences, and social posts`,`Your complete cookbook launch kit — ready to publish`],generatingSteps:[`Analyzing your recipes, audience, and cookbook concept`,`Designing an agent to structure recipes into chapters, meal plans, and grocery lists`,`Configuring sales page copy, email launch sequence, and social content generation`,`Setting up your paid download package and full launch workflow`],featureSectionTitle:`From recipes to revenue`,featureCardTitles:[`Connects to your content stack`,`Outputs you can sell`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Drive, Canva, Shopify, Gmail — Computer builds your cookbook, designs assets, and launches your product across the tools you already use.`,`Formatted cookbook PDF. Weekly meal plans. Itemized grocery lists. Sales page copy. Email launch sequence. Social media posts ready to schedule.`],capabilitySectionTitle:`Your cookbook team, on autopilot`,capabilitySectionSubtitle:`Upload your recipes, step away, come back to a launch-ready cookbook business.`,capabilityCards:[{title:`Cookbook Organization`,description:`Computer can sort your recipes into themed chapters, add nutritional notes, and format everything into a polished, download-ready cookbook.`},{title:`Meal Plan Builder`,description:`Computer can generate weekly meal plans from your recipes — balanced for your target audience's dietary goals — with itemized grocery lists for each week.`},{title:`Launch Copy Suite`,description:`Computer can write your sales page, a multi-email launch sequence, and a week of social posts — all tuned to your audience and cookbook theme.`},{title:`Connect Your Tools`,description:`Computer can publish to Google Docs, Google Drive, Shopify, Canva, and Gmail — build workflows across your entire content and commerce stack.`},{title:`Remember & Refine`,description:`Computer can remember your recipes, brand voice, and audience preferences across sessions — so every new cookbook or launch builds on what works.`},{title:`Monitor & Alert`,description:`Computer can track download sales and email performance — and flag when it's time to refresh content or launch a new edition.`}]});export{t as default};
